    fun get(name: String): ImageVector {
        val glyph = glyphs[name] ?: return Icons.Rounded.Tag
        return vectors.getOrPut(name) {
            val scale = 24f / maxOf(glyph.width, glyph.height)
            ImageVector.Builder(name, (glyph.width * scale).dp, (glyph.height * scale).dp,
                glyph.width, glyph.height)
                .addPath(PathParser().parsePathString(glyph.path).toNodes(), fill = SolidColor(Color.Black))
                .build()
        }
    }

